INSERT INTO "BusinessProfile" VALUES ('cmtnbneim000m7ddq3ot2hb4r', 'cmtnbneim000l7ddqi23nkhe4', 'Restaurang Kajutan', '5560123456', 'Göteborg', 'Kungsportsavenyen 12, 411 36 Göteborg', 'Västkustkök med råvaror från Fiskhamnen. 60 sittplatser.', NULL, '{RESTAURANG,FINE_DINING}', NULL, '2026-09-04 19:03:07.582', '2026-09-04 19:03:07.582');
INSERT INTO "BusinessProfile" VALUES ('cmtnbneip000o7ddqr7udows8', 'cmtnbneip000n7ddqqdhpgjn4', 'Bageri Solrosen', '5569876543', 'Göteborg', 'Andra Långgatan 4, 413 03 Göteborg', 'Surdegsbageri och kafé i Linné. Öppnar 07 varje dag.', NULL, '{BAGERI,CAFE}', NULL, '2026-09-04 19:03:07.585', '2026-09-04 19:03:07.585');
INSERT INTO "Campaign" VALUES ('cmtnbneir000q7ddqy94xeuna', 'cmtnbneim000m7ddq3ot2hb4r', 'Lansera vår nya lunchmeny', 'Vi byter till en ny lunchmeny med råvaror från Fiskhamnen. Du kommer förbi en vardag mellan 11 och 14, äter på vår bekostnad och gör innehåll som visar rätterna och stämningen i lokalen. Ta gärna med att lunchen kostar 145 kr inklusive kaffe.', '{RESTAURANG,MAT_OCH_DRYCK}', '{TIKTOK,INSTAGRAM}', '{TIKTOK_VIDEO,INSTAGRAM_STORY}', 'HYBRID', 400000, 30000, 3, 'Göteborg', 10000, '2026-09-04 19:03:07.587', '2026-11-03 19:03:07.587', 'ACTIVE', '2026-09-04 19:03:07.588', '2026-09-04 19:03:07.588');
INSERT INTO "Campaign" VALUES ('cmtnbneiu000s7ddqa59cqqsw', 'cmtnbneim000m7ddq3ot2hb4r', 'Smakmeny för matintresserade', 'Sexrättersmeny med dryckespaket för dig som gör innehåll om fine dining. Vi vill ha en längre film där du berättar om rätterna och köket.', '{FINE_DINING,RESTAURANG}', '{YOUTUBE,INSTAGRAM}', '{YOUTUBE_VIDEO,INSTAGRAM_POST}', 'HYBRID', 1200000, 240000, 1, 'Göteborg', 30000, '2026-09-04 19:03:07.59', '2026-11-03 19:03:07.587', 'ACTIVE', '2026-09-04 19:03:07.59', '2026-09-04 19:03:07.59');
INSERT INTO "Campaign" VALUES ('cmtnbneiv000u7ddqh0u2tz4f', 'cmtnbneip000o7ddqr7udows8', 'Morgonbröd och kaffe i Linné', 'Vi vill nå studenter och folk som jobbar hemifrån. Kom förbi på förmiddagen, visa surdegen och våra sittplatser. Nämn att vi öppnar 07.', '{BAGERI,CAFE}', '{TIKTOK,INSTAGRAM}', '{TIKTOK_VIDEO}', 'PRODUCT', 0, 40000, 5, 'Göteborg', 3000, '2026-09-04 19:03:07.591', '2026-09-18 19:03:07.587', 'ACTIVE', '2026-09-04 19:03:07.592', '2026-09-04 19:03:07.592');
INSERT INTO "Campaign" VALUES ('cmtnbnej000107ddqlvak6mcl', 'cmtnbneip000o7ddqr7udows8', 'Fredagsfika med kanelbullar', 'Vi bakade extra inför fredagen och ville visa det. En kortare film från disken och en story när bullarna kommer ut ur ugnen.', '{BAGERI,CAFE}', '{INSTAGRAM}', '{INSTAGRAM_REEL}', 'FIXED', 350000, 0, 1, 'Göteborg', 3000, '2026-08-05 19:03:07.596', '2026-08-23 19:03:07.596', 'CLOSED', '2026-09-04 19:03:07.597', '2026-09-04 19:03:07.597');
